import React from "react";
import { Link } from "react-router-dom";
import withRouter from "./withRouter";

class Post extends React.Component {

    constructor(props){
        super(props);

        const { id } = this.props.params;

        this.state = {
            post: {},
            comments: [],
            base_URL: "",
            loading: true,
            comment_text: "",
            like: null,
            count_like: null,
            id: id
        };
    }

    componentDidMount(){
        fetch("http://localhost:8000/api/post/" + this.state.id)
        .then(res => res.json())
        .then(json => {

            this.setState({
                post: json.post,
                comments: json.all_comment.data,
                base_URL: json.base_URL,
                like: json.post.is_like,
                count_like: json.like_qty.length,
                loading: false
            });

        })
        .catch(err=>{
            console.log(err);
            this.setState({loading:false});
        });
    }

    
    handleLike = (e) => {
        e.preventDefault();
        
        const prevLike = this.state.like;
        
        // optimistic UI
        this.setState({
            like: this.state.like ? 0 : 1,
            count_like: this.state.like ? this.state.count_like - 1 : this.state.count_like + 1
        });
        
        fetch("http://localhost:8000/api/like/" + this.state.post.id)
        .then(res => res.json())
        .then(data => {
            this.setState({
                like: data.status,
                count_like: data.count_like
            });
        })
        .catch(() => {
            // rollback
            this.setState({
                like: this.state.like,
                count_like: this.state.count_like
            });
        });
    };
    
    handleCommentChange = (e)=>{
        this.setState({
            comment_text:e.target.value
        });
    }
    
    handleSendComment = (e) => {
        e.preventDefault();

        const text = this.state.comment_text.trim();
        if (!text) return;

        fetch("http://localhost:8000/api/comment", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                post_id: this.state.post.id,
                text: text
            })
        })
        .then(res => res.json())
        .then(data => {

            const newComment = {
                name: data.user_name,
                img: data.user_img,
                pivot: { text: data.text }
            };

            this.setState(prev => ({
                comments: [newComment, ...prev.comments],
                comment_text: ""
            }));
        })
        .catch(err => console.log(err));
    };



    render(){

        if(this.state.loading){
            return <p>Loading...</p>
        }


        return(
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

                    <div className="card mb-4 shadow-sm item-back text-color overflow-hidden rounded-4 boder">

                        <img 
                            src={this.state.base_URL + this.state.post.img}
                            alt=""
                            className="post-img rounded-top-4"
                        />

                        <div className="card-body">

                            <h3 className="card-title">{this.state.post.title}</h3>

                            <p>{this.state.post.display_time}</p>

                            <p className="card-text">{this.state.post.description}</p>

                            <div className="d-flex align-items-center mb-3">

                                <img
                                    src={this.state.base_URL + this.state.post?.user?.img}
                                    alt=""
                                    className="user-img me-3 rounded-circle boder"
                                />

                                <div>
                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        {this.state.post?.user?.name}
                                    </Link>
                                </div>

                            </div>

                            <div className="d-flex align-items-center gap-2 mb-3">

                                <span id="span_like" onClick={this.handleLike} style={{cursor:"pointer"}}>
                                    {this.state.like ? (
                                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"
                                            fill="red" viewBox="0 0 24 24">
                                            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 
                                            2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 
                                            4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 
                                            3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 
                                            11.54L12 21.35z" />
                                        </svg>
                                    ) : (
                                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor"
                                            class="bi bi-heart-fill" viewBox="0 0 16 16">
                                            <path fill-rule="evenodd"
                                            d="M8 1.314C12.438-3.248 23.534 4.735 8 15
                                            -7.534 4.736 3.562-3.248 8 1.314z"/>
                                        </svg>
                                    )}
                                </span>


                            <span id="count_like">{this.state.count_like}</span>

                            </div>

                            <form>

                                <div className="mb-3">

                                    <textarea
                                        className="form-control"
                                        rows="2"
                                        placeholder="Write a comment..."
                                        value={this.state.comment_text}
                                        onChange={this.handleCommentChange}
                                    />

                                </div>

                                <button type="button" className="btn btn-theme boder">
                                    Send Comment
                                </button>

                            </form>

                        </div>
                    </div>

                    <div className="shadow-sm item-back p-4 mb-3 boder rounded-4">

                        <h5 className="mb-4">
                            Comments ({this.state.comments.length})
                        </h5>

                        {this.state.comments.map((c,index)=>(
                            
                            <div key={index} className="d-flex mb-3">

                                <img
                                    src={this.state.base_URL + c.img}
                                    alt=""
                                    className="user-img me-3 rounded-circle boder"
                                />

                                <div>

                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        {c.name}
                                    </Link>

                                    <p className="mb-0">{c.pivot.text}</p>

                                </div>

                            </div>

                        ))}

                    </div>

                </div>
            </main>
        )
    }

}

export default withRouter(Post);
